require dirname(__DIR__).'/bootstrap.php';
use App\Core\Csrf;
$token=preg_replace('/[^a-f0-9]/i','',$_GET['t']??'');$csrf=Csrf::token();
?><!doctype html><html lang="id"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="csrf-token" content="<?=htmlspecialchars($csrf)?>"><title>Kedai Bara — Pesan dari Meja</title><link rel="preconnect" href="https://fonts.googleapis.com"><link href="https://fonts.googleapis.com/css2?family=Fraunces:wght@600;700&family=Plus+Jakarta+Sans:wght@400;500;600;700;800&display=swap" rel="stylesheet"><link rel="stylesheet" href="assets/css/app.css"><script src="https://code.jquery.com/jquery-3.7.1.min.js"></script></head><body class="public-order-body"><header class="public-order-head"><div class="brand"><div class="brand-badge">KB</div><div><div class="brand-title">Kedai <span>Bara</span></div><div class="brand-sub" id="tableLabel">Digital Ordering</div></div></div><div class="public-cart-pill">Keranjang <b id="publicCartCount">0</b></div></header><main class="public-order-wrap"><section class="public-hero"><span class="hand-label">Pesan dari meja</span><h1>Pesan langsung, dapur langsung menerima.</h1><p>Pilih menu, modifier, dan catatan. Staff tetap akan membantu bila dibutuhkan.</p></section><div class="toolbar"><input class="control" id="pubSearch" placeholder="Cari menu..."><select class="control" id="pubCategory"><option value="">Semua kategori</option></select></div><div class="menu-grid" id="pubMenu"></div><section class="panel public-cart"><div class="panel-head"><h3>Pesanan Anda</h3></div><div id="pubCart"></div><div class="bill-total"><span>Total estimasi</span><strong id="pubTotal">Rp 0</strong></div><div class="form-grid"><label>Nama<input class="control" id="pubName" placeholder="Nama Anda"></label><label>Jumlah Tamu<input class="control" type="number" min="1" value="1" id="pubGuests"></label><label class="span-2">Catatan Order<textarea class="control" id="pubNotes" placeholder="Opsional"></textarea></label></div><button class="btn primary full" id="pubSubmit">Kirim ke Dapur</button></section></main><div id="toastRoot"></div><div class="modal-backdrop" id="modalBackdrop"><div class="modal" id="modalBox"></div></div>
<script>
(function($){const token=<?=json_encode($token)?>,csrf=document.querySelector('meta[name="csrf-token"]').content;let data={items:[],categories:[],groups:[],options:[],links:[]},cart=[];const esc=v=>String(v??'').replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]));const money=v=>'Rp '+Number(v||0).toLocaleString('id-ID',{maximumFractionDigits:0});function toast(m,e=false){$('.toast').remove();$('<div class="toast">').addClass(e?'error':'success').text(m).appendTo('body');setTimeout(()=>$('.toast').fadeOut(),3000)}function modal(h){$('#modalBox').html(h);$('#modalBackdrop').addClass('show')}function close(){$('#modalBackdrop').removeClass('show')}$(document).on('click','[data-close-modal]',close);$('#modalBackdrop').on('click',e=>{if(e.target.id==='modalBackdrop')close()});
function load(){$.getJSON('public_api.php',{action:'menu',token}).done(r=>{data=r.data;$('#tableLabel').text('Meja '+data.table.table_number);$('#pubCategory').html('<option value="">Semua kategori</option>'+data.categories.map(c=>`<option value="${c.id}">${esc(c.name)}</option>`).join(''));renderMenu();}).fail(x=>{$('#pubMenu').html('<div class="alert danger">'+esc(x.responseJSON?.message||'QR tidak valid.')+'</div>')})}function renderMenu(){const q=($('#pubSearch').val()||'').toLowerCase(),cat=+($('#pubCategory').val()||0),list=data.items.filter(m=>(!q||m.name.toLowerCase().includes(q))&&(!cat||+m.category_id===cat));$('#pubMenu').html(list.map(m=>`<button class="menu-tile pub-add" data-id="${m.id}"><span class="menu-station">${esc(m.preparation_station)}</span><strong>${esc(m.name)}</strong><small>${esc(m.description||'')}</small><b>${money(m.price)}</b></button>`).join(''))}$('#pubSearch,#pubCategory').on('input change',renderMenu);function groups(mid){const gids=data.links.filter(l=>+l.menu_item_id===+mid).map(l=>+l.modifier_group_id);return data.groups.filter(g=>gids.includes(+g.id)).map(g=>({...g,options:data.options.filter(o=>+o.group_id===+g.id&&+o.is_active===1)}))}$(document).on('click','.pub-add',function(){const m=data.items.find(x=>+x.id===+$(this).data('id')),gs=groups(m.id);if(!gs.length)return add(m,[],[],'');modal(`<h3>${esc(m.name)}</h3><form id="pubModForm" data-id="${m.id}" class="stack">${gs.map(g=>`<div class="modifier-group"><strong>${esc(g.name)}</strong><div class="modifier-options">${g.options.map(o=>`<label class="modifier-option"><input type="${+g.max_select===1?'radio':'checkbox'}" name="g${g.id}${+g.max_select===1?'':'[]'}" value="${o.id}"><span>${esc(o.name)} ${+o.price_delta?'<b>+'+money(o.price_delta)+'</b>':''}</span></label>`).join('')}</div><small class="muted">Pilih ${g.min_select}-${g.max_select}</small></div>`).join('')}<label>Catatan item<textarea class="control" name="notes"></textarea></label><div class="modal-actions"><button type="button" class="btn outline" data-close-modal>Batal</button><button class="btn primary">Tambah</button></div></form>`)});$(document).on('submit','#pubModForm',function(e){e.preventDefault();const m=data.items.find(x=>+x.id===+$(this).data('id')),ids=$(this).find('input:checked').map((_,x)=>+x.value).get(),opts=data.options.filter(o=>ids.includes(+o.id));add(m,ids,opts,$(this).find('[name=notes]').val());close()});function add(m,ids,opts,notes){cart.push({menu_id:+m.id,name:m.name,base:+m.price,extra:opts.reduce((s,o)=>s+(+o.price_delta),0),modifier_option_ids:ids,modifierNames:opts.map(o=>o.name),notes,qty:1});renderCart()}function renderCart(){const total=cart.reduce((s,x)=>s+(x.base+x.extra)*x.qty,0);$('#publicCartCount').text(cart.reduce((s,x)=>s+x.qty,0));$('#pubTotal').text(money(total));$('#pubCart').html(cart.length?cart.map((x,i)=>`<div class="cart-row"><div><strong>${esc(x.name)}</strong><div class="small muted">${esc(x.modifierNames.join(', '))}</div></div><div class="qty"><button class="pub-qty" data-i="${i}" data-d="-1">−</button><span>${x.qty}</span><button class="pub-qty" data-i="${i}" data-d="1">+</button><button class="text-btn danger pub-remove" data-i="${i}">×</button></div></div>`).join(''):'<div class="muted">Belum ada item.</div>'}$(document).on('click','.pub-qty',function(){const i=+$(this).data('i');cart[i].qty=Math.max(1,cart[i].qty+(+$(this).data('d')));renderCart()});$(document).on('click','.pub-remove',function(){cart.splice(+$(this).data('i'),1);renderCart()});$('#pubSubmit').on('click',function(){if(!cart.length)return toast('Pilih menu terlebih dahulu.',true);$.ajax({url:'public_api.php?action=create',method:'POST',dataType:'json',data:{_csrf:csrf,token,customer_name:$('#pubName').val()||'Guest',guest_count:$('#pubGuests').val(),notes:$('#pubNotes').val(),items:JSON.stringify(cart.map(x=>({menu_id:x.menu_id,qty:x.qty,notes:x.notes,modifier_option_ids:x.modifier_option_ids})))}}).done(r=>{toast(`Pesanan ${r.data.order_no} dikirim ke dapur.`);cart=[];renderCart();$('#pubNotes').val('')}).fail(x=>toast(x.responseJSON?.message||'Pesanan gagal.',true))});load();renderCart()})(jQuery);
</script></body></html>
